passages.append(make_passage(
    "非物质文化遗产的活态传承与青年创新 (Intangible Heritage & Youth Innovation)", "B2", "zh",
    "从景德镇窑火不熄的手工制瓷技艺，到苏州刺绣艺人巧夺天工的双面绣针法；从宜兴紫砂壶温润如玉的手工成型，到苗族银饰锻造中千锤百炼的繁密花纹，中国非物质文化遗产以其鲜活的生命力和高超的手工温度，展示了各民族劳动者世代相传的创造力。非物质文化遗产最大的特性在于其「活态性」——它依赖人的口传心授、手口相传而延续，一旦脱离了当下的日常生活场景与情感需求，就面临着技艺失传、后继乏人的断代危险。面对现代工业流水线产品的冲击，当代非遗保护工作彻底摆脱了过去「标本式冷藏」的被动局面，吹响了「见人见物见生活」的活态传承时代号角。令人欣喜的是，越来越多的「九零后」「零零后」年轻一代传承人正主动接棒，以天马行空的现代设计理念和青年话语体系赋予古老非遗前所未有的潮酷新生。年轻设计师将传统点翠、刺绣和盘扣工艺跨界融入高级时装与动漫国潮服饰；数字艺术家运用三维建模、虚拟现实和数字藏品，让敦煌壁画中的飞天乐器在屏幕前触手可及；非遗传承人更化身网络直播间里的主播，现场展示木雕雕刻、皮影戏操演或剪纸绝活，收获了数以千万计年轻网友的点赞与订单。当古老的东方技艺与年轻人的创新活力激情相遇，非遗便不再是博物馆展柜里落满灰尘的陈旧历史，而是重新化作流淌在当下中国人血液中的文化自信与时代新风尚。",
    {"非遗": "intangible cultural heritage", "景德镇": "Jingdezhen porcelain capital", "双面绣": "double-sided embroidery (Suzhou)", "紫砂壶": "Yixing purple clay teapots", "活态性": "living / dynamic nature of heritage", "口传心授": "teaching by word of mouth and demonstration", "见人见物见生活": "preserving people, objects, and living ways", "国潮": "China-chic / Guochao fashion", "点翠": "kingfisher feather inlay", "盘扣": "traditional Chinese frog fasteners"},
    [
        ("非物质文化遗产与普通物质文物相比，其最核心的存续特征是什么？", ["纯粹是石头材质", "依赖于人的活态传承、手艺代代口传心授", "完全不需要人来学习", "只要拍照存图即可"], 1, "非遗的生命力在于活态传承与代际手艺薪火相传。"),
        ("非遗保护中提出的「见人见物见生活」理念强调了怎样的保护路径？", ["把所有老手艺人关在博物馆里", "让非遗真正融入当代民众的烟火生活与日常应用中", "禁止任何手工艺品买卖", "把非遗书籍全部封存"], 1, "让古老技艺在当下的日常衣食住行中重新焕发生命。"),
        ("年轻一代非遗传承人通常采用哪些创新方式激活传统老技艺？", ["照本宣科绝不改变", "跨界国潮设计、数字建模VR展示以及短视频电商直播", "完全放弃手工改用机器", "隐藏手艺绝不外传"], 1, "结合时尚国潮设计、三维数字化与网络直播新形式。"),
        ("苏州刺绣以哪种巧夺天工的绝妙针法工艺享誉海内外？", ["双面绣", "简单缝合", "粗麻编织", "单色刺字"], 0, "苏绣的双面绣技艺展现了极为细腻神奇的手工艺术。"),
        ("古老非遗在当代青年群体中激发起的核心精神价值是什么？", ["崇拜古代封建制度", "深沉的文化自豪感、民族自信与审美新风尚", "单纯的猎奇心理", "抵制一切现代科学"], 1, "唤醒了青年一代发自内心的中华文化自信与认同。")
    ],
    [
        ("中国非物质文化遗产凝结了多民族世代传承的工匠精神。", ["正确", "错误"], 0, "正确。汇聚了各民族千百年来卓越的造物智慧。"),
        ("非物质文化遗产一旦进入博物馆展柜就可以永久高枕无忧。", ["正确", "错误"], 1, "错误。脱离生活场景的非遗容易丧失生命力而逐渐失传。"),
        ("当下很多青年设计师热衷将传统传统工艺融入现代时尚服饰。", ["正确", "错误"], 0, "正确。「国潮」兴起正是传统与现代美学的成功融汇。"),
        ("网络直播不仅没有帮助非遗传播，反而彻底毁掉了传统工艺。", ["正确", "错误"], 1, "错误。短视频和直播让非遗跨越圈层获得海量年轻拥趸。"),
        ("文化遗产的薪火相传离不开青年一代的创造性转化与发展。", ["正确", "错误"], 0, "正确。青年是推动非遗创新与活化传承的中坚生力军。")
    ]
))

